#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

banner "Finance Assistant Cloud SQL recovery qualification"

PROJECT_ID="comfforts-369117"
REGION="us-west1"
SOURCE_INSTANCE="aifa-staging-postgres"
DATABASE="aifa"
OWNER_DATABASE_USER="vtalwar.w@comfforts.com"
QUALIFICATION_ID="staging-cloud-sql-v1"
MIGRATION_ROLE="aifa-stg-migration@comfforts-369117.iam"
RUNTIME_ROLE="aifa-stg-runtime@comfforts-369117.iam"
RETENTION_ROLE="aifa-stg-retention@comfforts-369117.iam"
MIGRATION_JOB="aifa-staging-migrate"
QUALIFICATION_JOB="aifa-staging-qualify"
RETENTION_JOB="aifa-staging-retention"
ARTIFACT_REGISTRY_PREFIX="us-west1-docker.pkg.dev/comfforts-369117/aifa-containers/"
PROXY_IMAGE="${ARTIFACT_REGISTRY_PREFIX}cloud-sql-proxy@sha256:7d156a5c466e31596afd6c8ed134f19c207a297418392fdad2686524ca4e7a3c"
RUN_SUFFIX=$(date -u +%Y%m%d%H%M%S)
BACKUP_DESCRIPTION="Finance Assistant recovery qualification $RUN_SUFFIX"
BACKUP_RESTORE_INSTANCE="aifa-stg-backup-${RUN_SUFFIX}"
PITR_INSTANCE="aifa-stg-pitr-${RUN_SUFFIX}"
REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)
STAGING_ROOT="$REPO_ROOT/infrastructure/terraform/environments/staging"
BACKEND_PYTHON="$REPO_ROOT/backend/.venv/bin/python"
EVIDENCE_FILE="$REPO_ROOT/backend/artifacts/release/deployment/cloud-sql-recovery.v1.json"
ROLE_POLICY_FILE=$(mktemp)
PLAN_FILE="$STAGING_ROOT/recovery-qualification.tfplan"
OWNER_ELEVATED=0
DATA_API_ENABLED=0

cleanup_sensitive() {
  if (( OWNER_ELEVATED )); then
    warn "attempting to remove the temporary owner database user after an interrupted run"
    gcloud sql users delete "$OWNER_DATABASE_USER" \
      --project="$PROJECT_ID" \
      --instance="$SOURCE_INSTANCE" \
      --quiet >/dev/null 2>&1 || true
  fi
  if (( DATA_API_ENABLED )); then
    warn "attempting to disable temporary Cloud SQL Data API access after an interrupted run"
    gcloud sql instances patch "$SOURCE_INSTANCE" \
      --project="$PROJECT_ID" \
      --data-api-access=DISALLOW_DATA_API \
      --quiet >/dev/null 2>&1 || true
  fi
  rm -f "$ROLE_POLICY_FILE"
  rm -f "$PLAN_FILE"
}
trap cleanup_sensitive EXIT

latest_execution() {
  gcloud run jobs executions list \
    --project="$PROJECT_ID" \
    --region="$REGION" \
    --job="$1" \
    --sort-by='~metadata.creationTimestamp' \
    --limit=1 \
    --format='value(metadata.name)'
}

verify_recovered_target() {
  local target_instance="$1" target_connection="$2"
  gcloud run jobs execute "$QUALIFICATION_JOB" \
    --project="$PROJECT_ID" \
    --region="$REGION" \
    --wait \
    --container=operator \
    --args="-m","ai_finance_assistant.persistence.qualification","verify-recovery","--qualification-id","$QUALIFICATION_ID" \
    --container=cloud-sql-proxy \
    --args="--structured-logs","--private-ip","--auto-iam-authn","--address=0.0.0.0","--port=5432","$target_connection"
  say "Validated recovered synthetic state on $target_instance."
}

# ── Stage 1: exact-target and tool preflight ──────────────────────────────
stage "Verify identity, tools, and exact targets"
say "This wizard uses synthetic data and never captures a credential or secret value."
for tool in gcloud terraform jq git; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not available on PATH"; exit 1; }
done
[[ -x "$BACKEND_PYTHON" ]] || { warn "backend/.venv is not ready"; exit 1; }
ACTIVE_ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)')
ACTIVE_PROJECT=$(gcloud config get-value project 2>/dev/null)
CURRENT_BRANCH=$(git -C "$REPO_ROOT" branch --show-current)
[[ "$ACTIVE_ACCOUNT" == "$OWNER_DATABASE_USER" ]] || { warn "unexpected active account: $ACTIVE_ACCOUNT"; exit 1; }
[[ "$ACTIVE_PROJECT" == "$PROJECT_ID" ]] || { warn "unexpected active project: $ACTIVE_PROJECT"; exit 1; }
[[ "$CURRENT_BRANCH" == "main" ]] || { warn "run this qualification from merged main, not $CURRENT_BRANCH"; exit 1; }
[[ -z "$(git -C "$REPO_ROOT" status --short)" ]] || { warn "the repository must be clean before qualification"; exit 1; }
gcloud sql instances describe "$SOURCE_INSTANCE" --project="$PROJECT_ID" >/dev/null
say "Source: $PROJECT_ID/$REGION/$SOURCE_INSTANCE/$DATABASE"
say "Temporary backup target: $BACKUP_RESTORE_INSTANCE"
say "Temporary PITR target: $PITR_INSTANCE"
warn "The two temporary db-f1-micro targets are billable until Stage 7 deletes them."
confirm "Proceed with these exact targets and the approved temporary cost?" || exit 1
ask BACKEND_IMAGE "Paste the Artifact Registry backend image reference pinned by @sha256:"
[[ "$BACKEND_IMAGE" == "${ARTIFACT_REGISTRY_PREFIX}"*@sha256:* ]] || {
  warn "backend image must use the approved us-west1 Artifact Registry and a digest"
  exit 1
}
gcloud artifacts docker images describe "$BACKEND_IMAGE" \
  --project="$PROJECT_ID" --format='value(image_summary.digest)' >/dev/null
gcloud artifacts docker images describe "$PROXY_IMAGE" \
  --project="$PROJECT_ID" --format='value(image_summary.digest)' >/dev/null

# ── Stage 2: apply the reviewed operator jobs ─────────────────────────────
stage "Plan and apply the managed-state operator jobs"
terraform -chdir="$STAGING_ROOT" init -reconfigure \
  -backend-config="bucket=${PROJECT_ID}-aifa-tf-staging" \
  -backend-config="prefix=foundation"
terraform -chdir="$STAGING_ROOT" plan -lock-timeout=5m \
  -var="backend_image=$BACKEND_IMAGE" \
  -out="$PLAN_FILE"
confirm "Apply only the reviewed staging plan shown above?" || exit 1
terraform -chdir="$STAGING_ROOT" apply "$PLAN_FILE"
rm -f "$PLAN_FILE"
for job in "$MIGRATION_JOB" "$QUALIFICATION_JOB" "$RETENTION_JOB"; do
  gcloud run jobs describe "$job" --project="$PROJECT_ID" --region="$REGION" >/dev/null
done
SOURCE_IMAGE=$(gcloud run jobs describe "$QUALIFICATION_JOB" \
  --project="$PROJECT_ID" \
  --region="$REGION" \
  --format=json | jq -er \
  '.spec.template.spec.template.spec.containers[] | select(.name == "operator") | .image')
[[ "$SOURCE_IMAGE" == *@sha256:* ]] || { warn "operator image is not digest pinned"; exit 1; }
say "Pinned qualification image: $SOURCE_IMAGE"

# ── Stage 3: temporary owner elevation and least-privilege bootstrap ──────
stage "Bootstrap PostgreSQL privileges and remove owner elevation"
warn "This stage temporarily assigns cloudsqlsuperuser to $OWNER_DATABASE_USER."
warn "It also temporarily enables the authorized Cloud SQL Data API for the reviewed grant script."
confirm "Enable that path and create or update the exact IAM database user?" || exit 1
gcloud sql instances patch "$SOURCE_INSTANCE" \
  --project="$PROJECT_ID" \
  --data-api-access=ALLOW_DATA_API \
  --quiet
DATA_API_ENABLED=1
if gcloud sql users list --project="$PROJECT_ID" --instance="$SOURCE_INSTANCE" \
  --format='value(name,type)' | grep -Fq "$OWNER_DATABASE_USER"; then
  gcloud sql users assign-roles "$OWNER_DATABASE_USER" \
    --project="$PROJECT_ID" \
    --instance="$SOURCE_INSTANCE" \
    --type=CLOUD_IAM_USER \
    --database-roles=cloudsqlsuperuser \
    --revoke-existing-roles
else
  gcloud sql users create "$OWNER_DATABASE_USER" \
    --project="$PROJECT_ID" \
    --instance="$SOURCE_INSTANCE" \
    --type=CLOUD_IAM_USER \
    --database-roles=cloudsqlsuperuser
fi
OWNER_ELEVATED=1
"$BACKEND_PYTHON" -m ai_finance_assistant.persistence.privileges \
  --database="$DATABASE" \
  --schema=public \
  --migration-role="$MIGRATION_ROLE" \
  --runtime-role="$RUNTIME_ROLE" \
  --retention-role="$RETENTION_ROLE" > "$ROLE_POLICY_FILE"
say "Reviewing generated grants before execution:"
sed 's/^/  /' "$ROLE_POLICY_FILE"
confirm "Execute these least-privilege grants through the Cloud SQL Data API?" || exit 1
gcloud sql instances execute-sql "$SOURCE_INSTANCE" \
  --project="$PROJECT_ID" \
  --database="$DATABASE" \
  --sql="@$ROLE_POLICY_FILE" \
  --partial-result-mode=FAIL_PARTIAL_RESULT
gcloud sql users delete "$OWNER_DATABASE_USER" \
  --project="$PROJECT_ID" \
  --instance="$SOURCE_INSTANCE" \
  --quiet
OWNER_ELEVATED=0
gcloud sql instances patch "$SOURCE_INSTANCE" \
  --project="$PROJECT_ID" \
  --data-api-access=DISALLOW_DATA_API \
  --quiet
DATA_API_ENABLED=0
if gcloud sql users list --project="$PROJECT_ID" --instance="$SOURCE_INSTANCE" \
  --format='value(name)' | grep -Fxq "$OWNER_DATABASE_USER"; then
  warn "temporary owner database user still exists"
  exit 1
fi
SOURCE_DATA_API=$(gcloud sql instances describe "$SOURCE_INSTANCE" \
  --project="$PROJECT_ID" --format='value(settings.dataApiAccess)')
[[ "$SOURCE_DATA_API" != "ALLOW_DATA_API" ]] || { warn "Cloud SQL Data API remains enabled"; exit 1; }
say "Temporary database elevation and Data API access removed."

# ── Stage 4: migrate and prepare recoverable synthetic state ──────────────
stage "Migrate and prepare synthetic qualification state"
gcloud run jobs execute "$MIGRATION_JOB" \
  --project="$PROJECT_ID" --region="$REGION" --wait
MIGRATION_EXECUTION=$(latest_execution "$MIGRATION_JOB")
gcloud run jobs execute "$QUALIFICATION_JOB" \
  --project="$PROJECT_ID" --region="$REGION" --wait
PREPARE_EXECUTION=$(latest_execution "$QUALIFICATION_JOB")
PREPARED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)
say "Waiting until the PITR window includes the committed synthetic marker."
PITR_TIMESTAMP=""
for _attempt in $(seq 1 20); do
  RECOVERY_WINDOW=$(gcloud sql instances get-latest-recovery-time "$SOURCE_INSTANCE" \
    --project="$PROJECT_ID" --format=json)
  CANDIDATE=$(printf '%s' "$RECOVERY_WINDOW" | jq -r '.latestRecoveryTime // empty')
  if [[ -n "$CANDIDATE" ]] && "$BACKEND_PYTHON" -c \
    'from datetime import datetime; import sys; p=datetime.fromisoformat(sys.argv[1].replace("Z","+00:00")); c=datetime.fromisoformat(sys.argv[2].replace("Z","+00:00")); raise SystemExit(0 if c >= p else 1)' \
    "$PREPARED_AT" "$CANDIDATE"; then
    PITR_TIMESTAMP="$CANDIDATE"
    break
  fi
  sleep 15
done
[[ -n "$PITR_TIMESTAMP" ]] || { warn "PITR window did not reach the prepared marker"; exit 1; }
BACKUP_ID=$(gcloud sql backups create \
  --project="$PROJECT_ID" \
  --instance="$SOURCE_INSTANCE" \
  --description="$BACKUP_DESCRIPTION" \
  --format='value(id)')
[[ -n "$BACKUP_ID" ]] || { warn "on-demand backup ID was not returned"; exit 1; }
BACKUP_NAME=""
for _attempt in $(seq 1 10); do
  BACKUP_NAME=$(gcloud sql backups list \
    --project="$PROJECT_ID" \
    --filter="description='$BACKUP_DESCRIPTION'" \
    --format="value(name)")
  [[ "$BACKUP_NAME" =~ ^projects/${PROJECT_ID}/backups/[[:alnum:]-]+$ ]] && break
  BACKUP_NAME=""
  sleep 2
done
[[ -n "$BACKUP_NAME" ]] || { warn "unique on-demand backup name was not returned"; exit 1; }
say "Backup $BACKUP_NAME (run ID $BACKUP_ID) and PITR timestamp $PITR_TIMESTAMP are ready."

# ── Stage 5: create both temporary recovery targets ───────────────────────
stage "Restore the backup and point-in-time targets"
confirm "Create both reviewed temporary recovery instances now?" || exit 1
BACKUP_RESTORE_STARTED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)
BACKUP_RESTORE_STARTED_EPOCH=$(date -u +%s)
gcloud sql backups restore "$BACKUP_NAME" \
  --project="$PROJECT_ID" \
  --restore-instance="$BACKUP_RESTORE_INSTANCE" \
  --region="$REGION" \
  --database-version=POSTGRES_17 \
  --edition=enterprise \
  --tier=db-f1-micro \
  --storage-type=SSD \
  --storage-size=10 \
  --network="projects/$PROJECT_ID/global/networks/aifa-staging" \
  --no-assign-ip \
  --ssl-mode=ENCRYPTED_ONLY \
  --no-backup \
  --no-final-backup \
  --no-retain-backups-on-delete \
  --no-deletion-protection \
  --quiet
gcloud sql instances patch "$BACKUP_RESTORE_INSTANCE" \
  --project="$PROJECT_ID" \
  --database-flags=cloudsql.iam_authentication=on \
  --quiet
PITR_RESTORE_STARTED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)
gcloud sql instances clone "$SOURCE_INSTANCE" "$PITR_INSTANCE" \
  --project="$PROJECT_ID" \
  --point-in-time="$PITR_TIMESTAMP" \
  --quiet
gcloud sql instances patch "$PITR_INSTANCE" \
  --project="$PROJECT_ID" \
  --no-deletion-protection \
  --no-backup \
  --no-final-backup \
  --no-retain-backups-on-delete \
  --quiet
# ── Stage 6: validate recovered state on both targets ─────────────────────
stage "Validate both recovered targets"
for target in "$BACKUP_RESTORE_INSTANCE" "$PITR_INSTANCE"; do
  TARGET_DESCRIPTION=$(gcloud sql instances describe "$target" \
    --project="$PROJECT_ID" --format=json)
  printf '%s' "$TARGET_DESCRIPTION" | jq -e \
    '.state == "RUNNABLE" and
     .settings.ipConfiguration.ipv4Enabled == false and
     any(.settings.databaseFlags[]?; .name == "cloudsql.iam_authentication" and .value == "on")' \
    >/dev/null
  TARGET_CONNECTION=$(printf '%s' "$TARGET_DESCRIPTION" | jq -r '.connectionName')
  verify_recovered_target "$target" "$TARGET_CONNECTION"
  if [[ "$target" == "$BACKUP_RESTORE_INSTANCE" ]]; then
    BACKUP_VERIFY_EXECUTION=$(latest_execution "$QUALIFICATION_JOB")
  else
    PITR_VERIFY_EXECUTION=$(latest_execution "$QUALIFICATION_JOB")
    PITR_RESTORE_VALIDATED_EPOCH=$(date -u +%s)
  fi
done
say "Both private temporary instances contain the expected pre-recovery marker and schemas."

# ── Stage 7: source retention, cleanup, drift, and evidence ────────────────
stage "Verify retention, delete targets, and write evidence"
gcloud run jobs execute "$RETENTION_JOB" \
  --project="$PROJECT_ID" --region="$REGION" --wait
RETENTION_EXECUTION=$(latest_execution "$RETENTION_JOB")
gcloud run jobs execute "$QUALIFICATION_JOB" \
  --project="$PROJECT_ID" \
  --region="$REGION" \
  --wait \
  --container=operator \
  --args="-m","ai_finance_assistant.persistence.qualification","verify-retention","--qualification-id","$QUALIFICATION_ID"
RETENTION_VERIFY_EXECUTION=$(latest_execution "$QUALIFICATION_JOB")
warn "The next action deletes only $BACKUP_RESTORE_INSTANCE, $PITR_INSTANCE, and qualification backup $BACKUP_NAME."
confirm "Delete these validated temporary recovery resources?" || exit 1
gcloud sql instances delete "$BACKUP_RESTORE_INSTANCE" --project="$PROJECT_ID" --quiet
gcloud sql instances delete "$PITR_INSTANCE" --project="$PROJECT_ID" --quiet
gcloud sql backups delete "$BACKUP_NAME" \
  --project="$PROJECT_ID" \
  --quiet
for target in "$BACKUP_RESTORE_INSTANCE" "$PITR_INSTANCE"; do
  if gcloud sql instances describe "$target" --project="$PROJECT_ID" >/dev/null 2>&1; then
    warn "temporary instance still exists: $target"
    exit 1
  fi
done

set +e
terraform -chdir="$STAGING_ROOT" plan -lock-timeout=5m \
  -var="backend_image=$BACKEND_IMAGE" \
  -detailed-exitcode
DRIFT_EXIT=$?
set -e
[[ "$DRIFT_EXIT" -eq 0 ]] || { warn "final Terraform plan is not drift-free"; exit 1; }

OBSERVED_RTO_MINUTES=$(( (PITR_RESTORE_VALIDATED_EPOCH - BACKUP_RESTORE_STARTED_EPOCH + 59) / 60 ))
OBSERVED_RPO_MINUTES=$("$BACKEND_PYTHON" -c \
  'from datetime import datetime; import math,sys; s=datetime.fromisoformat(sys.argv[1].replace("Z","+00:00")); p=datetime.fromisoformat(sys.argv[2].replace("Z","+00:00")); print(max(0, math.ceil((s-p).total_seconds()/60)))' \
  "$PITR_RESTORE_STARTED_AT" "$PITR_TIMESTAMP")
(( OBSERVED_RPO_MINUTES <= 5 )) || { warn "observed RPO exceeds five minutes"; exit 1; }
(( OBSERVED_RTO_MINUTES <= 240 )) || { warn "observed RTO exceeds four hours"; exit 1; }
QUALIFICATION_FINISHED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)

jq -n \
  --arg qualification_date "$(date -u +%Y-%m-%d)" \
  --arg source_image_digest "$SOURCE_IMAGE" \
  --arg migration_execution "$MIGRATION_EXECUTION" \
  --arg prepare_execution "$PREPARE_EXECUTION" \
  --arg retention_execution "$RETENTION_EXECUTION" \
  --arg retention_verify_execution "$RETENTION_VERIFY_EXECUTION" \
  --arg backup_verify_execution "$BACKUP_VERIFY_EXECUTION" \
  --arg pitr_verify_execution "$PITR_VERIFY_EXECUTION" \
  --arg backup_id "$BACKUP_ID" \
  --arg backup_name "$BACKUP_NAME" \
  --arg pitr_timestamp "$PITR_TIMESTAMP" \
  --arg backup_instance "$BACKUP_RESTORE_INSTANCE" \
  --arg pitr_instance "$PITR_INSTANCE" \
  --arg started_at "$BACKUP_RESTORE_STARTED_AT" \
  --arg finished_at "$QUALIFICATION_FINISHED_AT" \
  --argjson observed_rpo_minutes "$OBSERVED_RPO_MINUTES" \
  --argjson observed_rto_minutes "$OBSERVED_RTO_MINUTES" \
  '{
    schema_version: "1",
    qualification_date: $qualification_date,
    status: "qualified",
    requirements: ["PR-017", "QR-005", "QR-006", "QR-007", "QR-010", "QR-011", "QR-014", "QR-015", "EVAL-20"],
    decisions: ["ADR-019", "ADR-029", "ADR-030-proposed"],
    scope: {project: "comfforts-369117", region: "us-west1", source_instance: "aifa-staging-postgres", synthetic_data_only: true, regional_disaster_recovery_claimed: false},
    source_image_digest: $source_image_digest,
    job_execution_names: {migration: $migration_execution, prepare: $prepare_execution, retention: $retention_execution, retention_verify: $retention_verify_execution, backup_verify: $backup_verify_execution, pitr_verify: $pitr_verify_execution},
    backup_id: $backup_id,
    backup_name: $backup_name,
    pitr_timestamp: $pitr_timestamp,
    temporary_instance_names: [$backup_instance, $pitr_instance],
    started_at: $started_at,
    finished_at: $finished_at,
    observed_rpo_minutes: $observed_rpo_minutes,
    observed_rto_minutes: $observed_rto_minutes,
    targets: {rpo_minutes: 5, rto_minutes: 240},
    validation_results: {backup_restore: "passed", point_in_time_recovery: "passed", migration: "passed", isolation_restart: "passed", retention: "passed"},
    cleanup_results: {temporary_owner_database_user: "deleted", temporary_data_api_access: "disabled", source_synthetic_state: "deleted", qualification_backup: "deleted", backup_restore_instance: "deleted", pitr_instance: "deleted"},
    final_drift: "no changes",
    secrets_recorded: false,
    limitations: ["Same-project staging shares administrative, quota, and billing blast radius.", "Single-zone recovery qualification is not regional disaster-recovery evidence."]
  }' > "$EVIDENCE_FILE"
jq -e '.status == "qualified" and .secrets_recorded == false' "$EVIDENCE_FILE" >/dev/null
trap - EXIT
cleanup_sensitive
say "Wrote recovery evidence to $EVIDENCE_FILE."

finish
}

run_wizard "$@"; exit
